def page(c,title,paras,num,size=A4,subtitle='DEVELOPMENT DRAFT • NOT SUBMISSION-READY'):
 w,h=size;c.setFillColor(cream);c.rect(0,0,w,h,fill=1,stroke=0);c.setFillColor(red);c.setFont('Helvetica-Bold',12);c.drawString(45,h-44,'BERLINBITE / CLOUD PROGRAMMING');c.setFont('Helvetica',9);c.drawString(45,h-65,subtitle.replace('•','/'));c.setFillColor(ink);c.setFont('Arial-Bold',12 if title.startswith('Abstract') else 23);c.drawString(45,h-108,title)
 ps=ParagraphStyle('pagebody',parent=style)
 if size==landscape(A4): ps.fontSize=19;ps.leading=29;ps.spaceAfter=25
 if title.startswith('Abstract'): ps.alignment=TA_JUSTIFY;ps.spaceAfter=6
 flow=[Paragraph(p.replace('```bash','').replace('```','').replace('`','').replace('## ','').replace('|---|---|','').replace('|',' / '),ps) for p in paras]
 frame=Frame(57,65,w-114,h-193,leftPadding=0,rightPadding=0,topPadding=0,bottomPadding=0)
 frame.addFromList(flow,c)
 if flow: raise RuntimeError('Overflow '+title)
 if size==landscape(A4):
  flows=[['Visitor','Find a place','Plan an evening'],['Search','Confirm','Inspect','Save'],['Local FastAPI','Docker image','AWS Fargate'],['Google facts','Labelled estimates','General advice'],['CloudFront / WAF','ALB','Fargate x 2'],['Bootstrap','Secrets + image','Enable app'],['Validate input','Limit traffic','Monitor health'],['12 tests pass','Docker passes','Live tests pending'],['Alternatives','Tradeoffs','Next iteration'],['Keys','Live tests','Plan + approve','Deploy']]
  items=flows[num-1];bw=(w-114-18*(len(items)-1))/len(items)
  for i,label in enumerate(items):
   x=57+i*(bw+18);c.setFillColor(HexColor('#ffffff'));c.setStrokeColor(red);c.roundRect(x,92,bw,52,8,fill=1,stroke=1);c.setFillColor(ink);c.setFont('Arial',11);c.drawCentredString(x+bw/2,114,label)
   if i<len(items)-1:c.line(x+bw,118,x+bw+18,118)
 c.setStrokeColor(red);c.line(45,46,w-45,46);c.setFont('Helvetica',9);c.drawString(45,30,'Prepared 24 September 2026 | Source and verification status in README');c.drawRightString(w-45,30,str(num));c.showPage()

concept=[
'<b>Problem and user.</b> Berlin visitors and residents need a quick way to identify a restaurant and plan an evening. Our persona is an English-speaking visitor meeting a friend for dinner. The goal is restaurant discovery and transparent planning support, without accounts or booking complexity.',
'<b>Product.</b> Search live Google Places results, confirm a restaurant, select a Berlin-local visit time and read “Tonight at a Glance.” Cards separate provider facts, unknown information and a clearly labelled crowd heuristic. Save only place identifiers in local browser storage.',
'<b>Architecture.</b> Browser → CloudFront HTTPS/WAF → Application Load Balancer → two FastAPI/Fargate tasks across two availability zones. ECR holds the portable image. Secrets Manager supplies credentials. CloudWatch records logs and alarms. Terraform describes the infrastructure. Both tasks access Google Places, Open-Meteo and optional OpenAI over HTTPS.',
'<b>Rationale and alternatives.</b> One Docker image runs locally or on AWS. Service adapters isolate providers. Standard ECS exposes architecture choices for the portfolio. App Runner was rejected after verifying its closure to new customers. Lambda and a separate S3 frontend remain alternatives. Omitting a database reduces cost but saved lists do not sync.',
'<b>Best practices and limits.</b> Two tasks, health checks and CPU scaling support availability. Secrets stay out of source. WAF limits traffic. Public-subnet tasks avoid NAT costs and accept inbound traffic only from the ALB. The CloudFront-to-ALB hop is HTTP in this draft; a domain and ACM certificate are needed for end-to-end TLS. Always-on resources incur cost.',
'<b>Data science and honesty.</b> Crowd labels use unvalidated time rules, not live occupancy or a trained model. English support and reservations stay unverified. Google editorial text is displayed separately and is not sent to OpenAI. Future ML requires licensed observations and evaluation.',
'<b>Status.</b> Code is drafted and basic static/scoring checks passed. All 12 automated tests, Docker runtime checks and Terraform validation passed. Live-data and AWS deployment verification remain pending. The student must review the code and institutional AI-use rules before submission.'
]
c=canvas.Canvas(str(OUT/'Phase-1-concept-DRAFT.pdf'),pagesize=A4);page(c,'Concept and architecture',concept,1);# A separate architecture figure accompanies the approximately one-page concept.
w,h=A4;c.setFillColor(cream);c.rect(0,0,w,h,fill=1,stroke=0);c.setFillColor(ink);c.setFont('Arial-Bold',22);c.drawString(45,h-65,'Architecture / proposed deployment')
boxes=[(170,660,255,48,'Browser / CloudFront HTTPS + WAF'),(170,565,255,48,'Application Load Balancer'),(45,455,230,55,'FastAPI / Fargate / AZ A'),(320,455,230,55,'FastAPI / Fargate / AZ B'),(45,330,145,55,'Google Places'),(225,330,145,55,'Open-Meteo'),(405,330,145,55,'OpenAI')]
